-- The two checklists published on 2026-10-20: Getting Outside After Days
-- Indoors (Outdoors) and When a Neighbor Problem Needs Raising (Neighbors).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-20`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('getting-outside-after-days-indoors', 'Getting Outside After Days Indoors', 'For the stretch when you have not been outside in days and the door feels heavier than it is. It sets the bar at the end of the street, puts the first trip in daylight, and asks for five still minutes out there rather than a brisk walk.', 'Outdoors', '["Set the bar at the end of the street — a short walk still counts as having been out.", "Go before you are properly dressed for it — a coat over what you have on will do.", "Put the first trip in daylight if you can — morning light does more for you than an evening walk.", "Pick a route with no errand attached — a run to the store is useful, not restorative.", "Or take the long way to something you need — the mailbox or the trash can carry the trip.", "Leave the headphones off for part of it — outside sounds different when you can hear it.", "Sit on a bench instead of turning back — five still minutes out there is the whole point.", "Notice what the air felt like once you are in — that is the part worth remembering tomorrow."]'::jsonb, 'daily', array['Movement', 'Self-Care']::text[], 1, '2026-10-20T16:00:00+00:00'::timestamptz),
  ('when-a-neighbor-problem-needs-raising', 'When a Neighbor Problem Needs Raising', 'For the noise, the parking or the fence that has been bothering you for weeks. It gets the specifics down, puts a knock before a note, names the one change that would fix it, and keeps the whole thing off the neighborhood group.', 'Neighbors', '["Write down the dates and times it happened — specifics travel further than a general complaint.", "Ask whether they could even know it is a problem — plenty of noise has never been mentioned to anyone.", "Knock before you write a note — a note is easy to keep and hard to answer.", "Open with the problem, not the person — the hours and the bins, not what kind of neighbor they are.", "Say what would fix it in one sentence — “after ten on weeknights” is something they can actually do.", "Keep it off the neighborhood group — an audience turns a small thing permanent.", "Know your next step before you knock — the landlord, the association, the city, in that order.", "Decide what you can live with — you will still share a wall with them tomorrow."]'::jsonb, 'as needed', array['Assertiveness', 'Boundaries']::text[], 1, '2026-10-20T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
